from common import *

R = "RSK"

au(R, 1, title="Enterprise and security risk management framework and method",
   status="proposed-target-state",
   rationale="Business plan sections 13.02 (risk management) and 18.x (risk register summary and reassessment triggers) describe intended practice in draft. No adopted method, completed assessment or risk owner was located.",
   target="Our risk method follows ISO/IEC 27005-style assessment within an ISO/IEC 27001 and NIST CSF 2.0 structure: assets, threats, vulnerabilities, likelihood and impact are scored on a documented scale, including fraud and AI-agent misuse scenarios. A full assessment runs at least annually and is re-run on defined triggers (new data category, new integration, new autonomous permission, material incident, new regulated customer type). Threat models produced with Tutela for each product feed the enterprise register. The managing member owns the process; an independent advisor reviews results.",
   current="Not established; draft plan text only.",
   intended="Adopt method and perform first assessment before first production customer.",
   provable="Draft business plan sections only.",
   statement="A documented risk management method and first formal risk assessment are planned but not yet completed.",
   kind="planned", controls=["RSK-001"], evrs=["RSK-001", "RSK-005"],
   requirements=["SOC2-013", "SOC2-030"], freshness="P1Y", mechanism="periodic-manual", automation="partial",
   impl="low", recur="low",
   oq=["Is ISO/IEC 27005 to be seeded as a source? It is not in SEED-IDS."],
   qd=dict(sub="Risk management framework", concern="The vendor identifies and evaluates risks systematically.",
           risk="Material risks to customer data and operations go unidentified.",
           src=[S("SRC-AICPA-TSC", "CC3.1"), S("SRC-AICPA-TSC", "CC3.2"), S("SRC-NIST-CSF-2.0", "GV.RM-01"), S("SRC-ISO-27001-2022", "6.1.2"), S("SRC-SA-SIG", rel="informed-by")],
           ind=ALLI, rc="certification-criteria", prod=ALLP),
   questions=[
    Q("Describe your enterprise and information security risk management framework and the standard or method it is based on.",
      ["Do you have a documented risk management program?", "Which risk framework do you follow?"], imp="high"),
    Q("How often do you perform a formal risk assessment, and which events trigger an out-of-cycle reassessment?",
      ["When was your last risk assessment?"], src=[S("SRC-AICPA-TSC", "CC3.4"), S("SRC-ECH-BUSINESS-PLAN", rel="informed-by")]),
    Q("How do you score likelihood and impact, and is the scoring method documented so another assessor would reach similar results?",
      ["Describe your risk rating methodology."], imp="medium"),
    Q("Who owns risk management, and how are significant risks escalated to the governing body?",
      ["Who is accountable for risk?"], src=[S("SRC-NIST-CSF-2.0", "GV.RR-02"), S("SRC-AICPA-TSC", "CC3.1")]),
    Q("Does your risk assessment explicitly consider fraud, including fraud by insiders, customers, external parties and misuse of AI agents?",
      ["Do you perform a fraud risk assessment?"], src=[S("SRC-AICPA-TSC", "CC3.3"), S("SRC-OWASP-AGENTIC-AI", rel="informed-by")], ind=FIN + DAF),
   ])

au(R, 2, title="Risk register, treatment tracking and effectiveness",
   status="proposed-target-state",
   rationale="BP section 18 is a risk register summary in draft prose. No machine-readable register linked to controls or evidence exists.",
   target="We maintain a machine-readable risk register in which each risk has an owner, inherent and residual rating, treatment decision, linked controls (ECTL-, UNB-CTRL-) and linked evidence requirements. Treatment actions have due dates; overdue actions raise an exception automatically. Effectiveness is judged from control evidence and incident data, not from completion of tasks. Risks arising from our own size and stage (key-person dependence, limited runway, customer concentration) are in the register and summarized to customers under NDA.",
   current="Not established.",
   intended="Create register as records under Praxis with validation that every high risk links to at least one control and evidence requirement.",
   provable="Nothing operational.",
   statement="A linked risk register is planned. A summary of key risks, including our own early-stage business risks, can be discussed under NDA.",
   kind="planned", controls=["RSK-001"], evrs=["RSK-001"],
   requirements=["SOC2-034", "SOC2-035"], freshness="P30D", mechanism="continuous-automated", automation="high",
   impl="low", recur="low",
   qd=dict(sub="Risk register and treatment", concern="Identified risks are owned, treated and tracked to closure.",
           risk="Known risks remain untreated or treatments are assumed effective without evidence.",
           src=[S("SRC-ISO-27001-2022", "6.1.3"), S("SRC-NIST-CSF-2.0", "GV.RM-03", "informed-by"), S("SRC-COSO-ERM-2017", rel="informed-by")],
           ind=ALLI, rc="certification-criteria", prod=ALLP),
   questions=[
    Q("Provide a summary of your top risks, their owners and treatment status.", ["Share your risk register (redacted)."], disc="public"),
    Q("Is each risk linked to the controls that treat it and to evidence that those controls operate?",
      ["How do you trace risks to controls?"], imp="medium"),
    Q("How do you track risk treatment actions to completion, and what happens when a due date is missed?",
      ["Describe your risk remediation tracking."]),
    Q("How do you determine whether a risk treatment actually reduced the risk?",
      ["How do you measure control effectiveness against risks?"], imp="medium", rc="customer-preference"),
    Q("Are risks from your own business model, such as a small team, early stage and concentration on a few customers, recorded in your register and disclosed to customers?",
      ["What are the biggest risks to your company itself?"], imp="high", rc="customer-preference",
      src=[S("SRC-ECH-BUSINESS-PLAN", rel="informed-by"), D("SRC-INTERAGENCY-TPRM-2023")]),
   ])

au(R, 3, title="Risk appetite, tolerance and risk acceptance authority",
   status="proposed-target-state",
   rationale="No risk appetite statement or acceptance authority exists. Unbound requirements place risk appetite for sponsor operations with the sponsor board (UNB-GOV-001), which is distinct from Echelon's own appetite.",
   target="The managing member has approved a risk appetite statement with measurable tolerances for security, availability, data integrity and compliance. Residual risks above tolerance can be accepted only by the managing member and only with a recorded decision; any acceptance that affects a customer's data or obligations is disclosed to that customer, who can object. Because one person may both propose and accept a risk, every acceptance above a defined rating is reviewed by an independent advisor within 30 days and the review is recorded. Risks to sponsor operations remain the sponsor board's to accept (UNB-GOV-001).",
   current="Not established.",
   intended="Adopt appetite statement and acceptance workflow using Praxis decision records.",
   provable="Nothing.",
   statement="A risk appetite statement and risk acceptance procedure are planned but not yet adopted.",
   kind="planned", controls=["RSK-003", "GOV-002"], evrs=["RSK-001", "GOV-003"],
   requirements=["UNB-GOV-001", "SOC2-033"], freshness="per-event", mechanism="event-driven-automated", automation="partial",
   impl="low", recur="low",
   challenge=CH(
     customer_intent="Risks are accepted deliberately by someone with authority, not by default or self-interest.",
     adverse_outcome="Risky shortcuts are accepted quietly by the person who benefits from them.",
     conventional_control_effectiveness="Segregation between risk proposer and approver is impossible inside a one-person company; a signature from the same person adds little.",
     legally_required="No; certification criteria (ISO 27001 6.1.3) require risk owners to approve treatment plans and residual risk.",
     contractually_required="Sometimes, via notice obligations for risks affecting the customer.",
     historical_convention="Risk committee approval in larger firms.",
     architectural_elimination="Structural controls that make certain risks unacceptable by construction (for example SEC-DB-001 denies dynamic SQL) remove whole classes from the acceptance process.",
     automatic_enforcement="Exceptions and acceptances are data with expiry, enforced by CI (RSK-004).",
     continuous_evidence="Decision records with independent reviewer attestation.",
     stronger_alternative="External independent reviewer plus customer disclosure for customer-affecting acceptances.",
     alternative_verifiable="Yes, via reviewer attestations and decision record history.",
     customer_acceptance_likelihood="Uncertain; depends on reviewer credibility.",
     invalidating_conditions="Reviewer not truly independent; disclosures not made.",
     conventional_cost="Risk committee: not feasible at this size.",
     alternative_cost="Advisor fees: low.",
     alternative_risks="Advisor rubber-stamping.",
     supporting_arguments=["Puts a second set of eyes where segregation is otherwise impossible."],
     opposing_arguments=["An advisor has no authority to block a decision.", "Customers may consider customer disclosure burdensome noise."],
     technical_effectiveness="equivalent", institutional_acceptance="uncertain"),
   qd=dict(sub="Risk appetite and acceptance", concern="Residual risk is accepted only within defined appetite by an authorized person.",
           risk="Excessive or self-serving risk acceptance exposes the customer.",
           src=[S("SRC-NIST-CSF-2.0", "GV.RM-02"), S("SRC-ISO-27001-2022", "6.1.3"), S("SRC-COSO-ERM-2017", rel="informed-by")],
           ind=ALLI, rc="certification-criteria", prod=ALLP),
   questions=[
    Q("Has your governing body defined risk appetite and tolerance, including for security, availability and data integrity?",
      ["Provide your risk appetite statement."]),
    Q("Who can accept residual risk, at what thresholds, and how is each acceptance recorded?",
      ["Describe your risk acceptance process."], imp="high"),
    Q("When an accepted risk affects our data or our obligations, will you inform us before accepting it?",
      ["Do you notify customers of risk acceptances that affect them?"], rc="customer-preference", imp="medium"),
    Q("In a very small organization, how do you prevent the same person from both proposing and accepting a risk?",
      ["How is segregation of duties achieved in risk acceptance?"], src=[S("SRC-ISO-27001-2022", "A.5.3"), S("SRC-AICPA-TSC", "CC1.3", "informed-by")], imp="medium"),
   ])

au(R, 4, title="Policy and standard exceptions with enforced expiry",
   status="proposed-target-state",
   rationale="The Secure Construction Standard requires exceptions to be explicit, narrowly scoped, time-limited, approved by an accountable reviewer and accompanied by compensating controls, with no silent bypasses; Unbound SOC2-033 requires recorded exceptions with expiration. Neither is implemented.",
   target="Every exception to a mandatory rule is a record naming the rule, scope (repository, path, environment), justification, compensating controls, approver and expiry. The build and release gates read the exception records: an expired exception makes the gate fail again, and a suppression without a matching record fails the build. Mandatory checks run in CI under branch protection that neither a human nor an AI agent can bypass without leaving an audit record; any bypass raises an alert. Open exception counts and the oldest exception age are reported monthly.",
   current="Not established.",
   intended="Implement exception records and gate integration in Praxis/CI as part of Secure Construction Standard adoption.",
   provable="Standard text only.",
   statement="Exceptions are intended to be time-limited records enforced by build gates. This mechanism is planned and not yet implemented.",
   kind="planned", controls=["RSK-002"], evrs=["RSK-002"],
   policies=["SEC-DB-001", "SEC-EXEC-001", "SEC-SUPPLY-001"], requirements=["SOC2-033"],
   freshness="P1D", mechanism="continuous-automated", automation="full", impl="medium", recur="low",
   challenge=CH(
     customer_intent="Exceptions do not become permanent, unmanaged holes.",
     adverse_outcome="Temporary waivers persist for years and are forgotten.",
     conventional_control_effectiveness="Spreadsheet exception logs with periodic review frequently go stale.",
     legally_required="No.",
     contractually_required="Rarely, beyond general compliance with security policy.",
     historical_convention="Exception register reviewed quarterly by security committee.",
     architectural_elimination="Not possible to eliminate the need for exceptions; the gate makes expiry self-enforcing.",
     automatic_enforcement="CI gate reads expiry and fails builds.",
     continuous_evidence="Gate logs and exception register snapshots per build.",
     stronger_alternative="Expiry enforced by machine rather than by review meeting.",
     alternative_verifiable="Yes, by inspecting gate configuration and build logs.",
     customer_acceptance_likelihood="Likely.",
     invalidating_conditions="Gate bypass by repository administrators; exceptions renewed by rote.",
     conventional_cost="Low.",
     alternative_cost="Medium initial engineering, low recurring.",
     alternative_risks="Release blocked by an expired exception during an incident; needs an emergency path with post-review.",
     supporting_arguments=["Turns a procedural control into an automatic one."],
     opposing_arguments=["Administrators of a tiny organization can still disable the gate; detection depends on audit logs the same person controls."],
     technical_effectiveness="stronger", institutional_acceptance="likely"),
   qd=dict(sub="Exceptions and waivers", concern="Departures from policy are controlled, temporary and visible.",
           risk="Unmanaged exceptions silently undermine controls.",
           src=[D("SRC-ECH-SCS-0.1"), D("SRC-ECH-UNB-SOC2-DIRECTIVE"), S("SRC-SA-SIG", rel="informed-by"), S("SRC-CSA-CAIQ-V4", rel="informed-by")],
           ind=ALLI, rc="industry-convention", prod=ALLP),
   questions=[
    Q("How are exceptions to security policies or standards requested, approved and recorded?",
      ["Describe your policy exception process."], imp="high"),
    Q("Do exceptions expire automatically, and what happens to the affected system when an exception expires?",
      ["Are exceptions time-bound?"]),
    Q("How many exceptions are open today, and how old is the oldest?",
      ["Provide exception metrics."], imp="medium", rc="customer-preference"),
    Q("Can an engineer or an AI agent bypass a mandatory build or release check, and how would you detect it?",
      ["Can required CI checks be skipped?"], src=[D("SRC-ECH-SCS-0.1"), S("SRC-NIST-SP800-218", rel="informed-by"), S("SRC-SLSA", rel="informed-by")],
      rc="echelon-internal"),
   ])

au(R, 5, title="Echelon's own third-party and fourth-party risk management",
   status="proposed-target-state",
   rationale="Business plan 12.02 (vendor governance) and 12.03 (strategic dependencies) are drafts. Unbound requires vendor inventory and subservice monitoring (SOC2-013, SOC2-022) and a per-tenant subprocessor register (UNB-XIN-SAS-011). No inventory or assessments exist.",
   target="We maintain an inventory of critical vendors, derived where possible from infrastructure-as-code, SBOM and billing data so it cannot silently drift, covering cloud hosting, code hosting, CI, AI model providers, email and support tooling. Each critical vendor has a criticality rating, assessment (SOC report review including complementary user entity controls we must operate, financial check, contract review), data classes received, AI training terms, incident notice terms and an exit plan. Reviews are annual and on change. Vendor incidents affecting customers are relayed within our contractual notice period.",
   current="Not established; vendors in use are not inventoried in any record located.",
   intended="Build inventory and assess the cloud, code hosting and AI providers first.",
   provable="Nothing.",
   statement="A formal inventory and assessment of our own critical vendors, including AI model providers, is planned and not yet complete.",
   kind="planned", controls=["RSK-004"], evrs=["RSK-003"],
   requirements=["SOC2-013", "SOC2-022", "UNB-XIN-SAS-011"], freshness="P1Y", mechanism="periodic-automated", automation="high",
   impl="medium", recur="low",
   oq=["Which AI model providers and agent runtimes does Echelon use for engineering, and under which commercial terms?"],
   qd=dict(sub="Fourth-party risk", concern="Risks from the vendor's own suppliers are identified and managed.",
           risk="A subcontractor or cloud provider failure or breach affects the customer without the vendor noticing.",
           src=[S("SRC-AICPA-TSC", "CC9.2"), S("SRC-NIST-CSF-2.0", "GV.SC-04"), S("SRC-ISO-27001-2022", "A.5.19"), D("SRC-INTERAGENCY-TPRM-2023"), S("SRC-SA-SIG", rel="informed-by")],
           ind=ALLI, prod=ALLP),
   questions=[
    Q("Do you maintain an inventory of your critical vendors and subprocessors, including cloud hosting, AI model providers, code hosting and CI services?",
      ["List your subprocessors.", "Who are your fourth parties?"], imp="critical"),
    Q("How do you assess the security and financial condition of critical vendors before onboarding and during the relationship?",
      ["Describe your vendor due diligence."], src=[S("SRC-NIST-CSF-2.0", "GV.SC-06"), S("SRC-NIST-SP800-53-R5", "SR-6")]),
    Q("Which AI model providers process data in delivering or building the service, what data do they receive, and do their terms allow retention or training on it?",
      ["Do you send our data to third-party AI services?"],
      src=[S("SRC-NIST-AI-RMF-1.0", rel="informed-by"), S("SRC-CSA-AICM", rel="informed-by"), S("SRC-ECH-UNB-SOC2-DIRECTIVE", rel="informed-by")],
      rc="customer-preference", imp="critical"),
    Q("How do you manage concentration risk where the failure of a single cloud provider or code host would stop your service?",
      ["Do you depend on a single cloud provider?"], src=[S("SRC-EU-DORA", "Art. 28", "informed-by"), S("SRC-FFIEC-BCM-BOOKLET", rel="informed-by")], ind=FIN),
    Q("Do you review the SOC reports of your subservice organizations and operate the complementary user entity controls they require of you?",
      ["How do you handle CUECs from your providers?"], src=[D("SRC-AICPA-SOC2-GUIDE"), D("SRC-ECH-UNB-SOC2-DIRECTIVE")]),
    Q("How do you learn of security incidents at your vendors, and how quickly would you pass relevant information to us?",
      ["Do your vendors notify you of breaches?"], src=[S("SRC-NIST-CSF-2.0", "GV.SC-08"), S("SRC-ISO-27001-2022", "A.5.21")]),
    Q("Do you have a documented exit plan for each critical vendor, and has any been tested?",
      ["How would you replace a critical supplier?"], src=[S("SRC-NIST-CSF-2.0", "GV.SC-10"), S("SRC-EU-DORA", "Art. 28", "informed-by")], imp="medium"),
   ])

au(R, 6, title="Risk assessment of AI agent use, new capabilities and model provider change",
   status="proposed-target-state",
   rationale="Unbound requires design review before new data categories, external APIs or autonomous permissions (SOC2-030) and bounded agent authority (SOC2-017, CNV-AIO-001). Echelon uses AI agents for engineering, as Praxis provenance records in these repositories show, but no documented AI risk assessment was located.",
   target="Before an AI agent receives a new tool, permission, data class or production pathway, a recorded risk assessment covers misuse, prompt injection, data leakage, unreviewed change and loss of attribution, mapped to NIST AI RMF and the OWASP agentic threat list, and names the controls (tool brokering, least privilege, human approval, provenance). Model or provider changes are treated as changes: pinned model identifiers, evaluation against regression suites before switching, and notice to customers where processing of their data changes.",
   current="Not established. AI agents perform engineering work in Echelon repositories; risk assessment of that use is not documented.",
   intended="Add AI-specific triggers to the risk method and a change record for model/provider changes.",
   provable="Praxis provenance records show agent identities on repository work, which evidences the use but not an assessment of it.",
   statement="AI agents are used in Echelon engineering work. A documented AI-specific risk assessment and model change procedure are planned.",
   kind="planned", controls=["RSK-001", "HR-004"], evrs=["RSK-001", "HR-006"],
   requirements=["SOC2-017", "SOC2-030", "CNV-AIO-001"], freshness="per-event", mechanism="event-driven-automated", automation="partial",
   impl="low", recur="low",
   qd=dict(sub="AI and change-driven risk", concern="Risks from AI agents and new capabilities are assessed before exposure.",
           risk="AI agents or new integrations introduce unassessed paths to customer data or consequential actions.",
           src=[D("SRC-NIST-AI-RMF-1.0"), S("SRC-OWASP-AGENTIC-AI", rel="informed-by"), S("SRC-ISO-23894-2023", rel="informed-by"), D("SRC-ECH-UNB-SOC2-DIRECTIVE")],
           ind=ALLI, rc="customer-preference", prod=ALLP),
   questions=[
    Q("How do you assess the risks of using AI agents to write code, operate systems or prepare customer communications?",
      ["Have you performed an AI risk assessment?"], imp="high"),
    Q("What risk review is required before you introduce a new data category, external integration or autonomous permission?",
      ["Do new features undergo security and privacy review?"], src=[D("SRC-ECH-UNB-SOC2-DIRECTIVE"), S("SRC-AICPA-TSC", "CC3.4")]),
    Q("How do you evaluate the risk of changes by your AI model providers, such as new model versions, deprecations or policy changes?",
      ["What happens when your AI provider changes its model?"], imp="medium"),
   ])

